/**
  * @selector .slds-nubbin_left
  * @restrict .slds-popover, .slds-dropdown
  * @modifier
  * @group nubbins
  */
.slds-nubbin_left,
.slds-nubbin--left {
  @include nubbin(left, 'before', inherit);
